// 5-Stage Classic Pipeline Structure (MIPS/RISC)
// Clock Cycle t
enum Stage {
    IF,   // Instruction Fetch (PC access, Instruction Read)
    ID,   // Instruction Decode (Register Read, Hazard Check)
    EX,   // Execute (ALU operation, Address calculation)
    MEM,  // Memory Access (Load/Store operation)
    WB    // Write Back (Write result to Register File)
};

// Throughput: IPC = 1 (Ideal CPI = 1)
// Latency: 5 cycles per instruction

// Data Hazard (RAW) Detection and Forwarding Check
// i-1 (EX/MEM) result needed by i (EX)
bool Hazard_EX_MEM = (ID.Rs == EX_MEM.WriteReg) && EX_MEM.RegWrite;
bool Hazard_MEM_WB = (ID.Rs == MEM_WB.WriteReg) && MEM_WB.RegWrite;

// Forwarding Logic Priority (Newest data first)
if (Hazard_EX_MEM) {
    ForwardA = EX_MEM.ALU_Result; // Bypass
} else if (Hazard_MEM_WB) {
    ForwardA = MEM_WB.Data_Out;
}


// Control Hazard Handling (Simple 1-Cycle Stall/Flush)
// Branch condition typically resolved in ID or EX stage.
if (Instruction_i.is_branch) {
    // Branch taken resolved in ID
    if (ID.Condition_Met) {
        // Pipeline Flush (Bubble insertion)
        EX_Stall = true;
        ID_Stall = true;
        // PC is updated to Target Address
        PC = ID.Branch_Target;
    }
}
